#requires -Version 7.0
Set-StrictMode -Version Latest
$ErrorActionPreference='Stop'
$script:Cfg=@{Root=(Resolve-Path (Join-Path $PSScriptRoot '..\..')).Path;Project='src\MemoAna\MemoAna.csproj';Tfm='net10.0-android';Config='Release';App='MemoAna';AppId='com.remotecodehub.memoana';Env='MEMOANA_ANDROID_SIGNING_ROOT';Keystore='memoana-upload-keystore.jks';Metadata='publishing-info.txt'}
function Log([string]$Message,[ValidateSet('Info','Success','Warning','Error','Step')][string]$Level='Info'){$m=@{Info=@('Gray','[INFO]');Success=@('Green','[ OK ]');Warning=@('Yellow','[WARN]');Error=@('Red','[FAIL]');Step=@('Cyan','[STEP]')};Write-Host "$(Get-Date -Format 'yyyy-MM-dd HH:mm:ss') $($m[$Level][1]) $Message" -ForegroundColor $m[$Level][0]}
function Section([string]$Title){Write-Host '';Write-Host ('='*78) -ForegroundColor Cyan;Write-Host " $Title" -ForegroundColor Cyan;Write-Host ('='*78) -ForegroundColor Cyan}
function EnsureDir([string]$Path){if(-not(Test-Path -LiteralPath $Path -PathType Container)){New-Item -ItemType Directory -Path $Path -Force|Out-Null}}
function Ask([string]$Prompt,[scriptblock]$Validator,[string]$ErrorMessage='Invalid value.',[switch]$Secret){while($true){if($Secret){$s=Read-Host "$Prompt (type CANCEL to abort)" -AsSecureString;$v=[Net.NetworkCredential]::new('',$s).Password}else{$v=Read-Host "$Prompt (type CANCEL to abort)"};if($v -ceq 'CANCEL'){throw 'Operation cancelled by user.'};try{if(& $Validator $v){return $v}}catch{Log $_.Exception.Message Warning};Log $ErrorMessage Warning;if((Read-Host 'Enter R to retry or C to cancel') -match '^[Cc]$'){throw 'Operation cancelled by user.'}}}
function StrongPassword([string]$v){return $v.Length -ge 12 -and $v -cmatch '[A-Z]' -and $v -cmatch '[a-z]' -and $v -match '\d' -and $v -match '[^a-zA-Z0-9]'}
function Paths([string]$root){$app=Join-Path $root 'MemoAna';$ks=Join-Path $app 'keystore';$md=Join-Path $app 'metadata';return @{Root=$root;App=$app;KeystoreDir=$ks;MetadataDir=$md;BackupDir=(Join-Path $app 'backup');ReleasesDir=(Join-Path $app 'releases');KeystorePath=(Join-Path $ks $script:Cfg.Keystore);MetadataPath=(Join-Path $md $script:Cfg.Metadata)}}
function SigningRoot{$v=[Environment]::GetEnvironmentVariable($script:Cfg.Env,'Machine');if([string]::IsNullOrWhiteSpace($v)){$v=[Environment]::GetEnvironmentVariable($script:Cfg.Env,'Process')};if([string]::IsNullOrWhiteSpace($v)){return $null};return [IO.Path]::GetFullPath($v)}
function ReadMetadata([string]$path){if(-not(Test-Path -LiteralPath $path -PathType Leaf)){throw "Metadata not found: $path"};$raw=Get-Content -LiteralPath $path -Raw;$d=@{};foreach($k in @('Upload Keystore','Keystore Alias','Store Password','Key Password','Certificate Subject')){$x=[regex]::Match($raw,"(?m)^$([regex]::Escape($k)):\r?\n(?<v>[^\r\n]*)");if($x.Success){$d[$k]=$x.Groups['v'].Value.Trim()}};foreach($k in @('Upload Keystore','Keystore Alias','Store Password','Key Password')){if([string]::IsNullOrWhiteSpace($d[$k])){throw "Missing metadata field: $k"}};return $d}
function RunCommand([string]$Command,[string[]]$Args,[int[]]$Sensitive=@()){$display=for($i=0;$i -lt $Args.Count;$i++){if($Sensitive -contains $i){'********'}else{$Args[$i]}};Log "Executing: $Command $($display -join ' ')";& $Command @Args;if($LASTEXITCODE -ne 0){throw "Command failed with exit code $LASTEXITCODE : $Command"}}
function ProjectProperty([string]$Name){$p=Join-Path $script:Cfg.Root $script:Cfg.Project;$x=[regex]::Match((Get-Content -LiteralPath $p -Raw),"<$Name>(?<v>[^<]+)</$Name>",'IgnoreCase');if($x.Success){return $x.Groups['v'].Value.Trim()};return $null}
